import { useState } from 'react';
import styles from './TransactionList.module.css';

const TransactionList = ({ transactions }) => {
  // Estado para controlar la visibilidad de los detalles de cada transacción
  const [visibleDetails, setVisibleDetails] = useState({});

  // Función para alternar la visibilidad de los detalles
  const toggleDetails = (index) => {
    setVisibleDetails((prev) => ({
      ...prev,
      [index]: !prev[index], // Alternar entre true y false
    }));
  };

  return (
    <ul className={styles.list}>
      {transactions.map((transaction, index) => (
        <li key={index} className={styles.item}>
          <div className={styles.header}>
            <p><strong>Descripción:</strong> {transaction.description}</p>
            <button
              className={styles.toggleButton}
              onClick={() => toggleDetails(index)}
            >
              {visibleDetails[index] ? 'Ocultar' : 'Mostrar'} detalles
            </button>
          </div>

          {visibleDetails[index] && ( // Mostrar detalles solo si están visibles
            <div className={styles.details}>
              <p><strong>Monto:</strong> ${transaction.amount}</p>
              <p><strong>Tipo:</strong> {transaction.type === 'income' ? 'Ingreso' : 'Gasto'}</p>
              <p><strong>Día:</strong> {transaction.day}</p>
              <p><strong>Hora:</strong> {transaction.time}</p>
            </div>
          )}
        </li>
      ))}
    </ul>
  );
};

export default TransactionList;
